/bin/bash -lc "python - <<'PY'
import numpy as np
for B in [(200,-50),(220,-60),(220,-90),(180,-70),(228,-20)]:
 for L1,L2 in [(140,95),(160,95),(160,105)]:
  B=np.array(B);W=np.array([134,46]); v=W-B;d=np.linalg.norm(v);a=(L1**2-L2**2+d*d)/(2*d)
  if abs(a)<=L1:
   h=np.sqrt(L1**2-a*a); e=B+a*v/d-h*np.array([-v[1],v[0]])/d
   print(tuple(B),L1,L2, 'E',e.round(1),'wrist elbow distance',np.linalg.norm(e-W))
PY"
